// An SVG image of the icon in the given color, as a data URL for Image.source.
function source(name, color) {
    const path = PATHS[name] || PATHS["error"];
    const svg = "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 -960 960 960'>"
        + "<path fill='" + color + "' d='" + path + "'/></svg>";
    return "data:image/svg+xml;utf8," + encodeURIComponent(svg);
}
